<script lang="ts">
 import type{DesignSnapshot,DesignOperation}from'@schubert/contracts';
 import{machiningNames,miterCut,type MachiningElement}from'@schubert/geometry';
 import MeasurementField from'./MeasurementField.svelte';
 import ReferencePicker from'../ReferencePicker.svelte';
 let{snapshot,feature,assets=[],documents=[],actorId='',canConfirm=false,disabled=false,onchange}:{snapshot:DesignSnapshot;feature:MachiningElement;assets?:any[];documents?:any[];actorId?:string;canConfirm?:boolean;disabled?:boolean;onchange:(ops:DesignOperation[])=>void}=$props();
 const host=$derived(snapshot.elements.find(e=>e.id===feature.hostElementId)),fullDepth=$derived(host?.kind==='stone_piece'&&feature.depthMeasureId===host.thicknessMeasureId),fastening=$derived(assets.filter(a=>a.kind==='technical_document'&&a.approved_at&&a.rights_verified));
 let error=$state('');
 function ownDepth(){const id=crypto.randomUUID();onchange([{type:'set_design_target',measureId:id,valueMm:null},{type:'set_machining_spec',elementId:feature.id,depthMeasureId:id}]);}
 function full(){if(host?.kind==='stone_piece')onchange([{type:'set_machining_spec',elementId:feature.id,depthMeasureId:host.thicknessMeasureId}]);}
 function miter(edgeIndex:number,angleDeg:string){error='';try{if(host?.kind!=='stone_piece')return;const angle=angleDeg.trim().replace(',','.');miterCut(snapshot,host,edgeIndex,angle,feature.face);onchange([{type:'set_machining_spec',elementId:feature.id,miter:{edgeIndex,angleDeg:angle}}]);}catch(problem){error=(problem as Error).message;}}
</script>
<div class="machining"><h3>{machiningNames[feature.machiningType]}</h3><p>Lokaler Bezug: {host?.label??'Bauteil fehlt'}. Die Bearbeitung bleibt mit diesem Materialkörper verbunden.</p>
 {#if feature.machiningType!=='cutout'}<label>Bearbeitungsseite<select value={feature.face??'front'} onchange={event=>onchange([{type:'set_machining_spec',elementId:feature.id,face:event.currentTarget.value as 'front'|'back'}])} {disabled}><option value="front">Vorderseite / lokale Oberfläche</option><option value="back">Rückseite / Unterseite</option></select></label>{/if}
 {#if feature.machiningType==='miter'&&host?.kind==='stone_piece'}<label>Gerade Bauteilkante<select value={String(feature.miter?.edgeIndex??0)} onchange={event=>miter(Number(event.currentTarget.value),feature.miter?.angleDeg??'')} {disabled}>{#each host.finishedContour.outer as edge,index}<option value={String(index)}>Kante {index+1} · {edge.from.xMm} / {edge.from.yMm} bis {edge.to.xMm} / {edge.to.yMm}</option>{/each}</select></label><label>Gehrungswinkel zur Fläche (Grad)<input inputmode="decimal" value={feature.miter?.angleDeg??''} onchange={event=>miter(feature.miter?.edgeIndex??0,event.currentTarget.value)} {disabled}/></label><p>Der Keil folgt Stärke, Winkel und Kantenbezug. Abgeleitete Koordinaten sind auf 0,01 mm quantisiert. Eine freie Verschiebung würde den Bezug zerstören und wird abgewiesen.</p>
 {:else if feature.machiningType!=='cutout'}{#if fullDepth}<p class="through">Ausdrücklich durch die gesamte Materialstärke. Änderungen der Stärke wirken auch auf diese Bohrung / Nut.</p><button type="button" class="btn small" onclick={ownDepth} {disabled}>Eigene Bearbeitungstiefe festlegen</button>{:else}<MeasurementField {snapshot} measureId={feature.depthMeasureId} label="Bearbeitungstiefe" elementId={feature.id} field="depthMeasureId" {actorId} {canConfirm} evidence={documents} {disabled} onchange={onchange}/><button type="button" class="btn small" onclick={full} {disabled}>Durch volle Materialstärke festlegen</button>{/if}{/if}
 <MeasurementField {snapshot} measureId={feature.minimumWebMeasureId} label={feature.machiningType==='miter'?'Erforderlicher verbleibender Querschnitt':'Erforderlicher Reststeg'} elementId={feature.id} field="minimumWebMeasureId" {actorId} {canConfirm} evidence={documents} {disabled} onchange={onchange}/>
 {#if feature.machiningType==='borehole'}<label for="fastening-source">Geprüfte Befestigungsunterlage</label><ReferencePicker id="fastening-source" reference="fastening-assets" initial={fastening.map(a=>({id:a.id,name:a.name??'Freigegebene technische Unterlage'}))} value={feature.confirmedFasteningAssetVersionId??''} onchange={value=>onchange([{type:'set_machining_spec',elementId:feature.id,confirmedFasteningAssetVersionId:value||null}])}/><p class="warning">Bohrschablonen benötigen eine passende, freigegebene Originalunterlage und die technische Freigabe dieses konkreten Planstands. Eine Eingabe oder Bildreferenz allein bestätigt keine Bohrpunkte.</p><a href="/product-assets">Originalunterlagen verwalten</a>{/if}
 {#if error}<p class="warning" role="alert">{error}</p>{/if}
</div>
<style>.machining{font-size:13px;line-height:1.65}.machining h3{font-size:14px;font-weight:600;margin:0 0 14px}.machining p{font-size:12px;color:var(--muted)}.machining label{display:block;font-size:13px;margin:16px 0}.machining input,.machining select{display:block;box-sizing:border-box;width:100%;font:inherit;font-size:14px;color:var(--ink);background:var(--paper);border:1px solid var(--line);border-radius:4px;padding:10px;margin-top:7px;min-height:44px}.through,.warning{background:var(--warning-wash);padding:12px;border:1px solid var(--line)}.machining a{color:var(--forest);font-size:12px}.machining input:focus-visible,.machining select:focus-visible{outline:2px solid var(--forest);outline-offset:2px}@media(max-width:720px){.machining input,.machining select,.machining button{font-size:16px;min-height:48px}}</style>
